def test_edge_case_exception_handling(self):
    """Test that other exceptions during subprocess calls are also handled"""
    from paper2remarkable.utils import check_pdftool

    # Mock subprocess.call to raise different exceptions for pdftk vs qpdf
    def mock_subprocess_call(args, **kwargs):
        if args[0] == "problematic_pdftk":
            raise PermissionError("Permission denied")
        elif args[0] == "qpdf":
            # qpdf should work normally
            return subprocess.call(["qpdf", "--help"], **kwargs)
        else:
            # Call original for other commands
            return subprocess.call(args, **kwargs)

    with patch('paper2remarkable.utils.subprocess.call', side_effect=mock_subprocess_call):
        # Should still continue and try qpdf when pdftk has permission error
        result = check_pdftool("problematic_pdftk", "qpdf")
        self.assertEqual(result, "qpdf")
